// === Tab: mySketch ===
let unit = (PG.PI ** PG.PHI);
const nums = 540;
const noiseScale = PG.PI * 400;

let a, b, c, d, e, f;
let group1;
let ac, bc, cc, aColor, bColor, cColor;
let sizes = [unit / 5, unit / 3];

/////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowWidth * 11 / 12, windowHeight * 7 / 8);
	background(15, 12, 22);

	noiseDetail(5, PG.PHI/2);

	noStroke();

	ac = rCol(15);
	bc = rCol(15);
	cc = rCol(15);

	aColor = removeColor("red");
	bColor = removeColor("red");
	cColor = removeColor("red");

	a = new ParticleGroup(aColor, nums, sizes);
	b = new ParticleGroup(bColor, nums, sizes);
	c = new ParticleGroup(cColor, nums, sizes);
	d = new ParticleGroup(ac, nums, sizes);
	e = new ParticleGroup(bc, nums, sizes);
	f = new ParticleGroup(cc, nums, sizes);

	group1 = [a, b, c, d, e, f];

	for (let group of group1) {
		ParticleGroup.populate(group);
	}

}




function draw() {
	for (let group of group1) {
		group.update();
	}
}

/////////////////////////////////////////////////////////////////////////

class ParticleGroup {

	static populate(aGroup) {
		for (let i = 0; i < aGroup.amount; i++) {
			let x = rInc(width, unit / TAU);
			let y = rInc(height, unit / TAU);
			let size = random(aGroup.sizeRange[0], aGroup.sizeRange[1])
			aGroup.container.push(new Particle(x, y, size));
		}
	}

	constructor(color, amount, sizeRange = [0.1, 0.3]) {
		this.color = color;
		this.sizeRange = sizeRange;
		this.amount = amount;
		this.container = [];
		this.populated = false;
	}

	update() {
		if (this.populated == false) {
			ParticleGroup.populate(this);
			this.populated = true;
		}

		for (let particles of this.container) {
			fill(this.color);
			particles.move();
			particles.checkEdge();
			particles.display();
		}
	}
}

/////////////////////////////////////////////////////////////////////////

class Particle {
	constructor(x, y, size) {
		this.dir = createVector(0, 0);
		this.vel = createVector(size / 2, size / 2);
		this.pos = createVector(x, y);
		this.speed = random([size * unit / 2, -size * unit / 2]);
		this.size = size;
		this.angle = TAU;
		this.noiseScale = noiseScale;
		this.well = false;
	}

	move() {
		this.angle = noise(this.pos.x / (this.noiseScale), this.pos.y / (this.noiseScale));
		this.angle *= TAU;

		this.vel.rotate((tan((this.angle) * ctg2(this.angle))));
		this.pos.add(this.vel);
	}

	checkEdge() {
		pgWrap(this.pos, [random(width / 32), width * 31 / 32 + random(width / 32), random(height / 18), height * 17 / 18 + random(height / 18)]);
	}

	display() {
		ellipse(this.pos.x, this.pos.y, this.size);
	}
}

//////////////////////////////////////////////////////////////////////////

function removeColor(pickRGB, cols = [ac, bc, cc]) {
	if (pickRGB === "red") {
		return color(0, green(random(cols)), blue(random(cols)), 15);
	} else if (pickRGB === "green") {
		return color(red(random(cols)), 0, blue(random(cols)), 15);
	} else if (pickRGB === "blue") {
		return color(red(random(cols)), green(random(cols)), 0, 15);
	}
}

